'use strict';

/**
* Simpson's rule integration
*/
function simpson( f, a, b, n ) {
	if ( typeof f !== 'function' ) {
		throw new TypeError( 'invalid argument. First argument must be a function.' );
	}
	if ( n <= 0 || n % 2 !== 0 ) {
		throw new Error( 'invalid argument. n must be a positive even integer.' );
	}

	var h = ( b - a ) / n;
	var sum = f( a ) + f( b );
	var i;
	var x;

	for ( i = 1; i < n; i++ ) {
		x = a + i * h;
		sum += ( i % 2 === 0 ? 2 : 4 ) * f( x );
	}
	return ( h / 3 ) * sum;
}

module.exports = simpson;
